tools.cdt.evaluate_script({ pageId: 1, waitForStableDom: true, function: `() => {
  const input = document.querySelector('input[name="delivery"]');
  if (!input) return { ok: false, reason: 'no time input' };
  const fire = (name) => {
    input.dispatchEvent(new Event(name, { bubbles: true }));
  };
  function forceValue(v){
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(input, v);
    fire('input'); fire('change');
  }
  // PrimeNG p-time-picker listens to input+change; also try programmatic via set.
  forceValue('19:30');
  return { afterSetValue: input.value };
}` })

