const pageId = 1;

// 1) Gather final values of every field.
const summary = await tools.cdt.evaluate_script({
  pageId,
  waitForStableDom: true,
  function: `() => {
    const val = (sel) => document.querySelector(sel)?.value ?? null;
    const isChecked = (sel) => !!document.querySelector(sel)?.checked;
    const isFilled = (sel) => {
      const el = document.querySelector(sel);
      return el ? (el.value !== '' && el.value != null) : false;
    };
    return {
      customerName: val('input[name="customer"]'),
      telephone:     val('input[name="telephone"]'),
      email:         val('input[name="email"]'),
      sizeSmall: isChecked('input[name="size"][value="small"]'),
      sizeMedium: isChecked('input[name="size"][value="medium"]'),
      sizeLarge:   isChecked('input[name="size"][value="large"]'),
      toppings: ['bacon','extraCheese','onion','mushroom'].map(n => ({n, on: isChecked('input[name="topping"][value="'+n+'"]')})),
      deliveryTimeInput: val('input[name="delivery"]'),
      deliveryInstructions: val('input[name="instructions"]'),
      // visible spinner state
      spinnerHours: document.querySelector('.timepicker-hours')?.textContent || null,
      spinnerMinutes: document.querySelector('.timepicker-minutes')?.textContent || null,
      spinnerAmPm: document.querySelector('.timepicker-ampm')?.textContent || null
    };
  }`
});

// 2) Take the screenshot and save it to /shots/t3-filled.png.
await tools.cdt.take_screenshot({
  pageId,
  format: "png",
  quality: 90,
  fullPage: false,
  filePath: "/shots/t3-filled.png"
});

return summary;

